export * from "@/components/plugins/offers/model";
export * from "@/components/plugins/offers/labels";
export * from "@/components/plugins/offers/list";
export * from "@/components/plugins/offers/editor";
export * from "@/components/plugins/offers/detail";

import { z } from "zod";

import type { Customer } from "@/components/plugins/customers/types";
import { customerDisplayName } from "@/components/plugins/customers/utils";

export const offerStatuses = ["draft", "pending", "accepted", "declined"] as const;
export type OfferStatus = (typeof offerStatuses)[number];
export const offerSortFields = [
  "number",
  "title",
  "date",
  "validUntil",
  "status",
  "net",
  "gross",
] as const;
export const offerDefaultSort = { field: "number", direction: "desc" } as const;
export const offerLineSchema = z.object({
  description: z.string().trim().min(1).max(2000),
  quantityMilli: z.int().min(1).max(10_000_000),
  unit: z.string().trim().max(40),
  priceMinor: z.int().min(0).max(2_147_483_647),
  discountBps: z.int().min(0).max(10000),
  taxBps: z.int().min(0).max(10000),
});
export const offerInputSchema = z
  .object({
    title: z.string().trim().min(1).max(200),
    date: z.iso.date(),
    validUntil: z.iso.date(),
    terms: z.string().trim().max(5000),
    notes: z.string().trim().max(5000),
    lines: z.array(offerLineSchema).max(200),
  })
  .refine((value) => value.validUntil >= value.date, {
    path: ["validUntil"],
    message: "Invalid validity date",
  });
export type OfferLine = z.output<typeof offerLineSchema>;
export type OfferInput = z.output<typeof offerInputSchema>;
export type OfferRecipient = Pick<
  Customer,
  "id" | "name" | "companyName" | "email" | "street" | "addressComplement" | "city"
>;
export function recipientAddressLines(r: OfferRecipient) {
  return [customerDisplayName(r), r.street, r.addressComplement, r.city].filter(
    (line): line is string => !!line,
  );
}
export function recipientSnapshot(customer: OfferRecipient): OfferRecipient {
  const { id, name, companyName, email, street, addressComplement, city } = customer;
  return { id, name, companyName, email, street, addressComplement, city };
}
export function emptyLine(): OfferLine {
  return {
    description: "",
    quantityMilli: 1000,
    unit: "",
    priceMinor: 0,
    discountBps: 0,
    taxBps: 0,
  };
}
export function emptyOffer(date: string): OfferInput {
  return { title: "", date, validUntil: date, terms: "", notes: "", lines: [] };
}
// Half-up rounding, once for the discounted line and once for its tax.
function rounded(n: bigint, d: bigint) {
  return Number((n + d / 2n) / d);
}
export function lineAmounts(line: OfferLine) {
  const net = rounded(
    BigInt(line.priceMinor) * BigInt(line.quantityMilli) * BigInt(10000 - line.discountBps),
    10_000_000n,
  );
  const tax = rounded(BigInt(net) * BigInt(line.taxBps), 10_000n);
  return { net, tax, gross: net + tax };
}
export function offerTotals(lines: readonly OfferLine[]) {
  let net = 0,
    gross = 0;
  const rates = new Map<number, number>();
  for (const line of lines) {
    const amounts = lineAmounts(line);
    net += amounts.net;
    gross += amounts.gross;
    rates.set(line.taxBps, (rates.get(line.taxBps) ?? 0) + amounts.tax);
  }
  return {
    net,
    gross,
    taxes: [...rates].sort(([a], [b]) => a - b).map(([rate, amount]) => ({ rate, amount })),
  };
}
export function formatOfferNumber(number: number) {
  return `#of-${number}`;
}

export function moneyFormatter(currency: string, locale: string) {
  const format = new Intl.NumberFormat(locale, { style: "currency", currency });
  const digits = format.resolvedOptions().maximumFractionDigits ?? 2;
  return { digits, format: (minor: number) => format.format(minor / 10 ** digits) };
}
export interface OfferSender {
  issuer: string;
  issuerAddress?: string;
}
export interface IssuedOffer extends OfferSender {
  token: string;
  number: number;
  currency: string;
  locale: string;
  issuedAt: string;
  recipient: OfferRecipient;
  content: OfferInput;
}
export interface Offer {
  id: string;
  number: number;
  customerId: string;
  currency: string;
  version: number;
  status: OfferStatus;
  draft: OfferInput | null;
  issued: IssuedOffer | null;
  sentAt: string | null;
}
export function displayedContent(offer: Offer) {
  return offer.issued?.content ?? offer.draft!;
}
export function issueOffer(
  offer: Offer,
  customer: OfferRecipient,
  metadata: Pick<IssuedOffer, "locale" | "issuer" | "issuerAddress" | "issuedAt" | "token">,
): Offer {
  if (!offer.draft || !offer.draft.lines.length || customer.id !== offer.customerId)
    throw new Error("INVALID");
  const content = offerInputSchema.parse(offer.draft);
  return {
    ...offer,
    status: "pending",
    sentAt: null,
    draft: null,
    version: offer.version + 1,
    issued: {
      ...metadata,
      number: offer.number,
      currency: offer.currency,
      recipient: recipientSnapshot(customer),
      content,
    },
  };
}
export interface OfferRow {
  id: string;
  number: number;
  customerId: string;
  customer: string;
  title: string;
  date: string;
  validUntil: string;
  currency: string;
  net: number;
  gross: number;
  status: OfferStatus;
  sent: boolean;
}
export function offerRow(offer: Offer, customer: OfferRecipient): OfferRow {
  const content = displayedContent(offer);
  const recipient = offer.issued?.recipient ?? customer;
  const { net, gross } = offerTotals(content.lines);
  return {
    id: offer.id,
    number: offer.number,
    customerId: offer.customerId,
    customer: recipient.companyName || recipient.name,
    title: content.title,
    date: content.date,
    validUntil: content.validUntil,
    currency: offer.currency,
    net,
    gross,
    status: offer.status,
    sent: !!offer.sentAt,
  };
}

"use client";
import { ArrowUpIcon, ArrowDownIcon, Trash2Icon, PlusIcon } from "lucide-react";
import { useRef, useState, type ComponentType, type ReactNode } from "react";

import { BackLink } from "@/components/back-link";
import { IconTooltip } from "@/components/icon-tooltip";
import { Link, type LinkProps } from "@/components/link";
import { NativeSelect } from "@/components/native-select";
import { inputClass, Feedback, useCustomerAction } from "@/components/plugins/customers/ui";
import { customerDisplayName } from "@/components/plugins/customers/utils";
import { offerLabels, type OfferLabels } from "@/components/plugins/offers/labels";
import {
  editLine,
  readLine,
  useOfferLineOrder,
  type OfferLineControls,
} from "@/components/plugins/offers/line-draft";
import {
  emptyLine,
  emptyOffer,
  formatOfferNumber,
  lineAmounts,
  moneyFormatter,
  offerInputSchema,
  offerLineSchema,
  offerTotals,
  recipientAddressLines,
  type OfferInput,
  type OfferLine,
  type Offer,
  type OfferRecipient,
  type OfferSender,
} from "@/components/plugins/offers/model";
import { RecordDeleteButton, useRecordDeletion } from "@/components/record-deletion";
import { cn } from "@/components/utils/cn";
import { destructiveActionClass } from "@/components/utils/destructive-action";
import {
  buttonClass,
  iconButtonClass,
  primaryClass,
  outlineButtonClass,
} from "@/components/utils/table-controls";
import {
  tableActionCellClass,
  tableActionHeaderClass,
  tableCellClass,
  tableClass,
  tableHeaderClass,
  tablePanelClass,
  tableRowClass,
} from "@/components/utils/table-styles";

const lineInputClass = cn(inputClass, "rounded-md px-2 md:h-8");
export function Recipient({ customer }: { customer: OfferRecipient }) {
  return (
    <address className="text-sm leading-relaxed not-italic">
      {recipientAddressLines(customer).map((line, i) => (
        <div key={i}>{line}</div>
      ))}
    </address>
  );
}
export function OfferAddresses({
  sender,
  recipient,
  customerHref,
  labels,
  customerPicker,
  linkComponent: A = Link,
}: {
  sender?: OfferSender;
  recipient?: OfferRecipient;
  customerHref?: string;
  labels: OfferLabels;
  customerPicker?: ReactNode;
  linkComponent?: ComponentType<LinkProps>;
}) {
  return (
    <div className="@container/addresses space-y-4">
      {sender && (
        <div className="@min-[32rem]/addresses:w-1/2">
          <h2 className="mb-1 text-sm text-muted-foreground">{labels.sender}</h2>
          <address className="text-sm leading-relaxed wrap-anywhere not-italic">
            <strong>{sender.issuer}</strong>
            {sender.issuerAddress && (
              <div className="whitespace-pre-line">{sender.issuerAddress}</div>
            )}
          </address>
        </div>
      )}
      <div
        className={
          sender ? "@min-[32rem]/addresses:ml-auto @min-[32rem]/addresses:w-1/2" : undefined
        }
      >
        {customerPicker ?? <h2 className="text-sm text-muted-foreground">{labels.recipient}</h2>}
        {recipient && (
          <div className="mt-1 wrap-anywhere">
            <Recipient customer={recipient} />
            {customerHref && (
              <A className="text-sm underline" href={customerHref}>
                {labels.editCustomer}
              </A>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
export function OfferTotals({
  lines,
  currency,
  locale,
  labels: l,
}: {
  lines: OfferLine[];
  currency: string;
  locale: string;
  labels: OfferLabels;
}) {
  const amounts = offerTotals(lines);
  const money = moneyFormatter(currency, locale).format;
  return (
    <dl
      aria-label={l.totals}
      className="ml-auto grid w-fit grid-cols-[1fr_auto] gap-x-8 gap-y-1 text-sm tabular-nums"
    >
      <dt>{l.net}</dt>
      <dd className="text-right">{money(amounts.net)}</dd>
      {amounts.taxes.map((t) => (
        <div key={t.rate} className="contents">
          <dt>
            {l.taxAmount} {t.rate / 100}%
          </dt>
          <dd className="text-right">{money(t.amount)}</dd>
        </div>
      ))}
      <dt className="font-bold">{l.gross}</dt>
      <dd className="text-right font-bold">{money(amounts.gross)}</dd>
    </dl>
  );
}
export const offerNumericColumnClass = "text-end whitespace-nowrap tabular-nums";

export const offerEditorLabels = {
  cancel: "Cancel",
  close: "Close",
  deleteOffer: "Delete offer",
  confirmDelete: "Delete",
  deleteDescription: (number: string) => `Delete offer ${number}? This action cannot be undone.`,
  deleted: "Offer deleted.",
  deleting: "Deleting…",
  reorderLine: "Reorder line",
};

export function OfferLinePosition({
  position,
  labels,
  controls,
}: {
  position: number;
  labels: Pick<OfferLabels, "up" | "down"> & Pick<typeof offerEditorLabels, "reorderLine">;
  controls?: OfferLineControls;
}) {
  return (
    <th
      scope="row"
      aria-label={String(position)}
      className={cn(tableCellClass, "py-0 text-start font-normal tabular-nums")}
    >
      {controls ? (
        <div className="flex items-center print:contents">
          <IconTooltip label={labels.reorderLine}>
            <button
              type="button"
              aria-label={labels.reorderLine + " " + position}
              aria-keyshortcuts="ArrowUp ArrowDown"
              className={cn(
                buttonClass,
                "-ms-1.5 touch-none px-1.5 font-normal select-none enabled:cursor-grab enabled:active:cursor-grabbing disabled:opacity-100 print:contents",
              )}
              disabled={!controls.moveUp && !controls.moveDown}
              {...controls.handle}
            >
              <span>{position}</span>
            </button>
          </IconTooltip>
          <div className="flex group-hover/offer-line:pointer-events-auto group-hover/offer-line:opacity-100 has-[:focus-visible]:opacity-100 print:hidden [@media(hover:hover)]:pointer-events-none [@media(hover:hover)]:opacity-0">
            {[
              { label: labels.up, Icon: ArrowUpIcon, move: controls.moveUp },
              { label: labels.down, Icon: ArrowDownIcon, move: controls.moveDown },
            ].map(({ label, Icon, move }) => (
              <IconTooltip key={label} label={label}>
                <button
                  type="button"
                  aria-label={label}
                  className={cn(buttonClass, "size-10 shrink-0 p-0 md:size-7 md:min-h-7")}
                  disabled={!move}
                  onClick={move}
                >
                  <Icon aria-hidden="true" />
                </button>
              </IconTooltip>
            ))}
          </div>
        </div>
      ) : (
        position
      )}
    </th>
  );
}

export function OfferLineTable({
  labels: l,
  children,
  totals,
  money,
  lineActions = false,
  inlineEditing = false,
  onAddLine,
  addLineDisabled,
}: {
  labels: OfferLabels;
  children: ReactNode;
  totals?: ReturnType<typeof offerTotals>;
  money: (amount: number) => string;
  lineActions?: boolean;
  inlineEditing?: boolean;
  onAddLine?: () => void;
  addLineDisabled?: boolean;
}) {
  return (
    <div className="overflow-x-auto">
      <table
        className={cn(
          tableClass,
          inlineEditing &&
            "not-print:min-w-[42rem] not-print:table-fixed not-print:wrap-anywhere not-print:[&_td]:whitespace-normal",
        )}
        aria-label={l.lines}
      >
        <thead>
          <tr className={tableRowClass}>
            <th
              scope="col"
              className={cn(tableHeaderClass, inlineEditing && "not-print:w-32 md:not-print:w-28")}
            >
              {l.position ?? offerLabels.position}
            </th>
            <th scope="col" className={tableHeaderClass}>
              {l.description}
            </th>
            {[
              [l.quantity, "not-print:w-[13%]"],
              [l.price, "not-print:w-[14%]"],
              [l.discount, "not-print:w-[12%]"],
              [l.tax, "not-print:w-[9%]"],
              [l.net, "not-print:w-[14%]"],
            ].map(([label, width], index) => (
              <th
                scope="col"
                key={index}
                className={cn(
                  tableHeaderClass,
                  offerNumericColumnClass,
                  inlineEditing && "not-print:whitespace-normal",
                  inlineEditing && width,
                )}
              >
                {label}
              </th>
            ))}
            {lineActions && (
              <th
                scope="col"
                className={cn(
                  tableActionHeaderClass,
                  onAddLine && "py-0 print:hidden",
                  inlineEditing && "not-print:w-12",
                )}
              >
                <span className="sr-only">{l.actions}</span>
                {onAddLine && (
                  <IconTooltip label={l.add}>
                    <button
                      type="button"
                      aria-label={l.add}
                      className={iconButtonClass}
                      disabled={addLineDisabled}
                      onClick={onAddLine}
                    >
                      <PlusIcon aria-hidden="true" />
                    </button>
                  </IconTooltip>
                )}
              </th>
            )}
          </tr>
        </thead>
        <tbody>{children}</tbody>
        {totals && (
          <tfoot>
            {[
              [l.net, totals.net] as const,
              ...totals.taxes.map(
                ({ rate, amount }) => [l.taxAmount + " " + rate / 100 + "%", amount] as const,
              ),
              [l.gross, totals.gross] as const,
            ].map(([label, amount]) => (
              <tr
                key={label}
                className="first:font-bold last:font-bold last:[&>*]:border-y last:[&>*]:border-border"
              >
                <td aria-hidden="true" />
                <th
                  scope="row"
                  colSpan={5}
                  className={cn(tableCellClass, "py-1 text-start [font-weight:inherit]")}
                >
                  {label}
                </th>
                <td
                  className={cn(
                    tableCellClass,
                    offerNumericColumnClass,
                    "sticky end-0 bg-card py-1",
                  )}
                >
                  {money(amount)}
                </td>
                {lineActions && <td aria-hidden="true" />}
              </tr>
            ))}
          </tfoot>
        )}
      </table>
    </div>
  );
}

export interface OfferEditorProps {
  offer?: Offer;
  sender?: OfferSender;
  customerId?: string;
  customers: readonly OfferRecipient[];
  today: string;
  currency: string;
  locale: string;
  backHref: string;
  getCustomerHref: (id: string) => string;
  onSave: (customerId: string, values: OfferInput, version?: number) => Promise<void>;
  onDelete?: (id: string, version: number) => Promise<void>;
  renderProductPicker?: (add: (line: OfferLine) => void) => ReactNode;
  labels?: Partial<OfferLabels & typeof offerEditorLabels>;
  linkComponent?: ComponentType<LinkProps>;
}
export function OfferEditor({
  offer,
  sender,
  customerId,
  customers,
  currency,
  locale,
  today,
  backHref,
  getCustomerHref,
  onSave,
  onDelete,
  renderProductPicker,
  labels,
  linkComponent: A = Link,
}: OfferEditorProps) {
  const l = { ...offerLabels, ...offerEditorLabels, ...labels };
  const { digits, format: money } = moneyFormatter(offer?.currency ?? currency, locale);
  const [base] = useState(() => ({
    version: offer?.version,
    values: offer?.draft ?? offer?.issued?.content ?? emptyOffer(today),
  }));
  const [values, setValues] = useState(base.values);
  const [lines, setLines] = useState(() =>
    base.values.lines.map((line) => editLine(line, digits, crypto.randomUUID())),
  );
  const [owner, setOwner] = useState(offer?.customerId ?? customerId ?? "");
  const customer = customers.find((c) => c.id === owner);
  const [invalid, setInvalid] = useState(false);
  const action = useCustomerAction(l.failed, offer?.id ?? customerId);
  const formRef = useRef<HTMLFormElement>(null);
  const version = base.version;
  const deletion = useRecordDeletion({
    items: offer ? [offer] : [],
    scope: offer?.id,
    getName: (item) => formatOfferNumber(item.number),
    onDelete: onDelete && version !== undefined ? (id) => onDelete(id, version) : undefined,
    label: l.deleteOffer,
    labels: { ...l, actionError: l.failed, pending: l.deleting },
    disabled: action.pending,
    returnFocus: formRef,
  });
  const pending = action.pending || deletion.pending;
  const parsed = lines.map((line) => readLine(line, digits));
  const validAmounts = parsed.map(
    (line) => offerLineSchema.safeParse({ ...line, description: "—" }).success,
  );
  const fields = [
    { field: "priceMinor", label: l.price, step: 10 ** -digits, min: 0 },
    { field: "discountBps", label: l.discount, step: 0.01, min: 0, max: 100 },
    { field: "taxBps", label: l.tax, step: 0.01, min: 0, max: 100 },
  ] as const;
  function add(line: OfferLine) {
    const next = editLine(line, digits, crypto.randomUUID());
    setLines((old) => [...old, next]);
  }
  function change(key: string, field: string, value: string) {
    setLines((old) => old.map((line) => (line.key === key ? { ...line, [field]: value } : line)));
  }
  const order = useOfferLineOrder(lines, setLines, pending);
  return (
    <div className="space-y-4">
      <BackLink href={backHref} linkComponent={A}>
        {l.back}
      </BackLink>
      <h1 className="text-2xl font-semibold">
        {offer ? l.editing + " " + formatOfferNumber(offer.number) : l.newOffer}
      </h1>
      <form
        ref={formRef}
        tabIndex={-1}
        className={tablePanelClass + " space-y-5"}
        onSubmit={(event) => {
          event.preventDefault();
          if (pending) return;
          const input = offerInputSchema.safeParse({ ...values, lines: parsed });
          setInvalid(!input.success || !customer);
          if (input.success && customer)
            void action.run(() => onSave(customer.id, input.data, base.version), l.saved);
        }}
      >
        <fieldset disabled={pending} className="min-w-0 space-y-5">
          <OfferAddresses
            sender={sender}
            recipient={customer}
            customerHref={customer && getCustomerHref(customer.id)}
            labels={l}
            linkComponent={A}
            customerPicker={
              <label className="block text-sm font-medium">
                {l.customer}
                <NativeSelect
                  className={inputClass}
                  value={owner}
                  required
                  disabled={!!(offer || customerId)}
                  onChange={(e) => setOwner(e.target.value)}
                >
                  <option value="">{l.choose}</option>
                  {customers.map((c) => (
                    <option key={c.id} value={c.id}>
                      {customerDisplayName(c)}
                    </option>
                  ))}
                </NativeSelect>
              </label>
            }
          />
          <section className="grid gap-3 sm:grid-cols-2">
            {(["title", "date", "validUntil"] as const).map((f) => (
              <label
                key={f}
                className={
                  f === "title"
                    ? "block text-sm font-medium sm:col-span-2"
                    : "block text-sm font-medium"
                }
              >
                {l[f]}
                <input
                  required
                  className={inputClass}
                  type={f === "title" ? "text" : "date"}
                  maxLength={200}
                  min={f === "validUntil" ? values.date : undefined}
                  value={values[f]}
                  onChange={(e) => setValues({ ...values, [f]: e.target.value })}
                />
              </label>
            ))}
          </section>
          <section className="space-y-3">
            <OfferLineTable
              labels={l}
              money={money}
              lineActions
              onAddLine={() => add(emptyLine())}
              addLineDisabled={lines.length >= 200}
              totals={validAmounts.every(Boolean) ? offerTotals(parsed) : undefined}
            >
              {lines.map((line, i) => (
                <tr
                  key={line.key}
                  className={cn(tableRowClass, "group/offer-line", order.rowClass(line.key))}
                >
                  <OfferLinePosition
                    position={i + 1}
                    labels={l}
                    controls={order.controls(line.key, i)}
                  />
                  <td className={cn(tableCellClass, "w-full")}>
                    <textarea
                      aria-label={l.description + " " + (i + 1)}
                      required
                      maxLength={2000}
                      rows={1}
                      className={cn(
                        lineInputClass,
                        "field-sizing-content min-h-10 min-w-40 py-1.5 md:h-auto md:min-h-8",
                      )}
                      value={line.description}
                      onChange={(e) => change(line.key, "description", e.target.value)}
                    />
                  </td>
                  <td className={tableCellClass}>
                    <div className="flex justify-end gap-1">
                      <input
                        aria-label={l.quantity + " " + (i + 1)}
                        className={cn(lineInputClass, "w-24 min-w-24 text-end tabular-nums")}
                        type="number"
                        required
                        min={0.001}
                        step={0.001}
                        value={line.quantityMilli}
                        onChange={(e) => change(line.key, "quantityMilli", e.target.value)}
                      />
                      <input
                        aria-label={l.unit + " " + (i + 1)}
                        className={cn(lineInputClass, "w-24 min-w-24")}
                        type="text"
                        maxLength={40}
                        value={line.unit}
                        onChange={(e) => change(line.key, "unit", e.target.value)}
                      />
                    </div>
                  </td>
                  {fields.map(({ field, label, ...limits }) => (
                    <td key={field} className={tableCellClass}>
                      <input
                        {...limits}
                        aria-label={label + " " + (i + 1)}
                        className={cn(lineInputClass, "w-24 min-w-24 text-end tabular-nums")}
                        required
                        type="number"
                        value={line[field]}
                        onChange={(e) => change(line.key, field, e.target.value)}
                      />
                    </td>
                  ))}
                  <td className={cn(tableCellClass, offerNumericColumnClass)}>
                    {validAmounts[i] ? money(lineAmounts(parsed[i]).net) : "—"}
                  </td>
                  <td className={tableActionCellClass}>
                    <IconTooltip label={l.remove}>
                      <button
                        type="button"
                        aria-label={l.remove}
                        className={cn(iconButtonClass, destructiveActionClass)}
                        onClick={() => setLines((old) => old.filter((r) => r.key !== line.key))}
                      >
                        <Trash2Icon aria-hidden="true" />
                      </button>
                    </IconTooltip>
                  </td>
                </tr>
              ))}
            </OfferLineTable>
            {lines.length < 200 && renderProductPicker?.(add)}
          </section>
          {(["terms", "notes"] as const).map((f) => (
            <label key={f} className="block text-sm font-medium">
              {l[f]}
              <textarea
                className={inputClass + " h-auto py-2"}
                maxLength={5000}
                value={values[f]}
                onChange={(e) => setValues({ ...values, [f]: e.target.value })}
              />
            </label>
          ))}
        </fieldset>
        <Feedback feedback={invalid ? { error: true, message: l.invalid } : action.feedback} />
        <div className="flex flex-wrap items-center gap-2">
          {offer && onDelete && (
            <RecordDeleteButton
              label={l.deleteOffer}
              className={destructiveActionClass}
              disabled={pending}
              onClick={(event) => deletion.open(offer.id, event.currentTarget)}
            />
          )}
          <div className="ms-auto flex flex-wrap justify-end gap-2">
            {offer &&
              (pending ? (
                <button type="button" className={outlineButtonClass} disabled>
                  {l.cancel}
                </button>
              ) : (
                <A href={backHref} className={outlineButtonClass}>
                  {l.cancel}
                </A>
              ))}
            <button className={primaryClass} type="submit" disabled={pending}>
              {l.save}
            </button>
          </div>
        </div>
        {deletion.dialog}
      </form>
    </div>
  );
}

"use client";
import {
  DownloadIcon,
  EyeIcon,
  MailIcon,
  Trash2Icon,
  SendIcon,
  ThumbsDownIcon,
  ThumbsUpIcon,
} from "lucide-react";
import { useId, useState, type ComponentType, type ReactNode } from "react";

import { BackLink } from "@/components/back-link";
import { IconTooltip } from "@/components/icon-tooltip";
import { ContentSidebarLayout } from "@/components/layouts/content-sidebar-layout";
import { Link, type LinkProps } from "@/components/link";
import { Feedback, StatusBadge, useCustomerAction } from "@/components/plugins/customers/ui";
import {
  OfferAddresses,
  OfferLinePosition,
  OfferLineTable,
  offerEditorLabels,
  offerNumericColumnClass,
} from "@/components/plugins/offers/editor";
import { InlineOfferField } from "@/components/plugins/offers/inline-field";
import { offerLabels, type OfferLabels } from "@/components/plugins/offers/labels";
import {
  editLine,
  readLine,
  useOfferLineOrder,
  type OfferLineDraft,
} from "@/components/plugins/offers/line-draft";
import { OfferBadge } from "@/components/plugins/offers/list";
import {
  emptyLine,
  lineAmounts,
  formatOfferNumber,
  moneyFormatter,
  offerTotals,
  offerInputSchema,
  offerLineSchema,
  type OfferInput,
  type OfferLine,
  type Offer,
  type OfferRecipient,
  type OfferSender,
} from "@/components/plugins/offers/model";
import { RecordDeleteButton, useRecordDeletion } from "@/components/record-deletion";
import { cn } from "@/components/utils/cn";
import { destructiveActionClass } from "@/components/utils/destructive-action";
import {
  buttonClass,
  iconButtonClass,
  outlineButtonClass,
  primaryClass,
} from "@/components/utils/table-controls";
import {
  tableActionCellClass,
  tablePanelClass,
  tableCellClass,
  tableRowClass,
} from "@/components/utils/table-styles";

const sidebarCardClass = "rounded-xl border border-border bg-card p-4 text-card-foreground";
const sidebarHeadingClass = "mb-2 border-b border-border pb-3 text-sm font-semibold";
const sidebarControlsClass = "flex flex-wrap gap-1 @min-[64rem]/content-sidebar:flex-col";
const sidebarButtonClass = cn(buttonClass, "justify-start text-start");

const rowButtonClass = cn(iconButtonClass, "border-0 bg-transparent md:size-7 md:min-h-7");
const rowControlClass =
  "group-hover:opacity-100 group-focus-within:opacity-100 [@media(hover:hover)]:opacity-0 print:hidden";

type DraftValues = Omit<OfferInput, "lines"> & { lines: OfferLineDraft[] };
type DraftSession = {
  version: number;
  initial: DraftValues;
  values: DraftValues;
};

export interface OfferDetailProps {
  offer: Offer;
  sender?: OfferSender;
  customer: OfferRecipient;
  locale: string;
  backHref: string;
  customerHref: string;
  /** @deprecated Supply onSave for inline editing. */
  editHref?: string;
  pdfHref?: string;
  pdfFallback?: ReactNode;
  onSave?: (version: number, values: OfferInput) => Promise<void>;
  onDelete?: (id: string, version: number) => Promise<void>;
  renderProductPicker?: (add: (line: OfferLine) => void) => ReactNode;
  onIssue?: (version: number) => Promise<void>;
  onDecision?: (version: number, decision: "accepted" | "declined") => Promise<void>;
  onSend?: (issuedToken: string) => Promise<void>;
  labels?: Partial<OfferLabels & typeof offerEditorLabels>;
  linkComponent?: ComponentType<LinkProps>;
}

export function OfferDetail(props: OfferDetailProps) {
  return <OfferDetailContent key={props.offer.id} {...props} />;
}

function OfferDetailContent({
  offer,
  sender,
  customer,
  locale,
  backHref,
  onSave,
  onDelete,
  renderProductPicker,
  pdfHref,
  pdfFallback,
  onIssue,
  onDecision,
  onSend,
  labels,
  linkComponent: A = Link,
}: OfferDetailProps) {
  const l = { ...offerLabels, ...offerEditorLabels, ...labels };
  const [showIssued, setShowIssued] = useState(false);
  const reviewingDraft = !!offer.draft && (!offer.issued || !showIssued);
  const content = reviewingDraft ? offer.draft! : offer.issued!.content;
  const { digits, format: money } = moneyFormatter(offer.currency, locale);
  const [draft, setDraft] = useState<DraftSession | null>(null);
  const [newLine, setNewLine] = useState<string>();
  const [invalid, setInvalid] = useState(false);
  const canEdit = !!onSave && (reviewingDraft || !offer.draft);
  const base = {
    ...content,
    lines: content.lines.map((line, i) => editLine(line, digits, String(i))),
  };
  const values = draft?.values ?? base;
  const parsed = values.lines.map((line) => readLine(line, digits));
  const validAmounts = parsed.map(
    (line) => offerLineSchema.safeParse({ ...line, description: "—" }).success,
  );
  const totals = validAmounts.every(Boolean) ? offerTotals(parsed) : undefined;
  const action = useCustomerAction(l.failed, offer.id);
  const saveAction = useCustomerAction(l.failed, offer.id);
  const recipient = reviewingDraft ? customer : offer.issued!.recipient;
  const titleId = `factory-offer-title-${useId()}`;
  const headingId = `factory-offer-sidebar-${useId()}`;
  const issued = reviewingDraft ? null : offer.issued;
  const issue = reviewingDraft && onIssue;
  const decide = issued && offer.status === "pending" && onDecision;
  const hasActions = onDelete || issue || decide;
  const sent = !!issued && !!offer.sentAt;
  const hasSend = issued && (pdfHref || pdfFallback || onSend || sent);
  const hasSidebar = hasActions || hasSend;
  const deletion = useRecordDeletion({
    items: [offer],
    scope: offer.id,
    getName: (item) => formatOfferNumber(item.number),
    onDelete: onDelete ? (id) => onDelete(id, offer.version) : undefined,
    label: l.deleteOffer,
    labels: { ...l, actionError: l.failed, pending: l.deleting },
    disabled: action.pending || saveAction.pending || !!draft,
  });
  const pending = action.pending || saveAction.pending || deletion.pending;
  const editable = canEdit && !pending;

  function update(apply: (previous: DraftValues) => DraftValues) {
    if (!editable) return;
    setInvalid(false);
    setDraft((previous) => {
      const initial = previous?.initial ?? base;
      const next = apply(previous?.values ?? initial);
      if (JSON.stringify(next) === JSON.stringify(initial)) return null;
      return { version: previous?.version ?? offer.version, initial, values: next };
    });
  }

  function updateLines(apply: (lines: OfferLineDraft[]) => OfferLineDraft[]) {
    update((previous) => ({ ...previous, lines: apply(previous.lines) }));
  }

  function add(line: OfferLine, focus = false) {
    if (values.lines.length >= 200) return;
    const next = editLine(line, digits, crypto.randomUUID());
    if (focus) setNewLine(next.key);
    updateLines((lines) => (lines.length < 200 ? [...lines, next] : lines));
  }

  function save() {
    if (!onSave || !draft || pending) return;
    const input = offerInputSchema.safeParse({ ...values, lines: parsed });
    if (!input.success) {
      setInvalid(true);
      return;
    }
    void saveAction.run(
      () => onSave(draft.version, input.data),
      l.saved,
      () => {
        setDraft(null);
        setShowIssued(false);
      },
    );
  }

  function field(name: "title" | "date" | "validUntil" | "notes" | "terms") {
    const date = name === "date" || name === "validUntil";
    const multiline = name === "terms" || name === "notes";
    return (
      <InlineOfferField
        label={l[name]}
        value={values[name]}
        onChange={
          editable ? (value) => update((previous) => ({ ...previous, [name]: value })) : undefined
        }
        type={date ? "date" : multiline ? "textarea" : "text"}
        min={name === "validUntil" ? values.date : undefined}
        maxLength={multiline ? 5000 : date ? undefined : 200}
        indicator={date || name === "title"}
      />
    );
  }

  const order = useOfferLineOrder(values.lines, updateLines, !editable);

  function lineField(
    line: OfferLineDraft,
    i: number,
    name: Exclude<keyof OfferLineDraft, "key">,
    label: string,
    display?: string,
  ) {
    const description = name === "description";
    const unit = name === "unit";
    return (
      <InlineOfferField
        label={label + " " + (i + 1)}
        value={line[name]}
        display={display}
        onChange={
          editable
            ? (value) =>
                updateLines((lines) =>
                  lines.map((item) => (item.key === line.key ? { ...item, [name]: value } : item)),
                )
            : undefined
        }
        type={description ? "textarea" : unit ? "text" : "decimal"}
        maxLength={description ? 2000 : unit ? 40 : undefined}
        contentEditable
        startEditing={description && newLine === line.key}
      />
    );
  }

  return (
    <article className="@container/offer-detail space-y-4">
      <BackLink href={backHref} linkComponent={A}>
        {l.back}
      </BackLink>
      <header
        className={cn(
          "flex flex-wrap items-start gap-2",
          hasSidebar && "@min-[64rem]/offer-detail:me-[23.5rem]",
        )}
      >
        <p className="font-semibold">{formatOfferNumber(offer.number)}</p>
        <div className="ms-auto">
          <OfferBadge status={reviewingDraft ? "draft" : offer.status} labels={l} />
        </div>
      </header>
      <ContentSidebarLayout
        sidebar={
          hasSidebar ? (
            <div className="space-y-4">
              {hasActions && (
                <aside aria-labelledby={headingId + "-actions"} className={sidebarCardClass}>
                  <header
                    className={cn(sidebarHeadingClass, "flex items-center justify-between gap-2")}
                  >
                    <h2 id={headingId + "-actions"}>{l.actions}</h2>
                    {onDelete && (
                      <RecordDeleteButton
                        label={l.deleteOffer}
                        className={destructiveActionClass}
                        disabled={pending || !!draft}
                        onClick={(event) => deletion.open(offer.id, event.currentTarget)}
                      />
                    )}
                  </header>
                  <div className={sidebarControlsClass}>
                    {issue && (
                      <button
                        type="button"
                        disabled={pending || !!draft || !content.lines.length}
                        className={cn(primaryClass, "justify-start text-start")}
                        onClick={() => void action.run(() => issue(offer.version), l.updated)}
                      >
                        <SendIcon aria-hidden="true" />
                        {offer.issued ? l.reissue : l.issue}
                      </button>
                    )}
                    {decide &&
                      (
                        [
                          ["accepted", l.accept, ThumbsUpIcon],
                          ["declined", l.decline, ThumbsDownIcon],
                        ] as const
                      ).map(([decision, label, Icon]) => (
                        <button
                          key={decision}
                          type="button"
                          className={sidebarButtonClass}
                          disabled={pending || !!draft}
                          onClick={() =>
                            void action.run(() => decide(offer.version, decision), l.updated)
                          }
                        >
                          <Icon aria-hidden="true" />
                          {label}
                        </button>
                      ))}
                  </div>
                </aside>
              )}
              {hasSend && (
                <aside aria-labelledby={headingId + "-send"} className={sidebarCardClass}>
                  <h2 id={headingId + "-send"} className={sidebarHeadingClass}>
                    {l.sendHeading}
                  </h2>
                  <div className={sidebarControlsClass}>
                    {pdfHref ? (
                      <>
                        <a
                          className={sidebarButtonClass}
                          href={pdfHref}
                          target="_blank"
                          rel="noreferrer"
                        >
                          <EyeIcon aria-hidden="true" />
                          {l.preview}
                        </a>
                        <a
                          className={sidebarButtonClass}
                          href={pdfHref}
                          download={`offer-${offer.number}.pdf`}
                        >
                          <DownloadIcon aria-hidden="true" />
                          {l.pdf}
                        </a>
                      </>
                    ) : (
                      pdfFallback
                    )}
                    {(onSend || sent) && (
                      <div className="flex flex-wrap items-center gap-1">
                        {onSend ? (
                          <button
                            type="button"
                            className={cn(sidebarButtonClass, !sent && "grow")}
                            disabled={pending || !!draft || sent}
                            onClick={() => void action.run(() => onSend(issued.token), l.sent)}
                          >
                            <MailIcon aria-hidden="true" />
                            {l.send}
                          </button>
                        ) : (
                          <span className="px-3 py-2 text-sm">{l.emailStatus}</span>
                        )}
                        {sent && (
                          <StatusBadge
                            value="sent"
                            options={[{ value: "sent", label: l.sent }]}
                            label={l.emailStatus}
                            className="bg-status-success text-status-success-foreground"
                            successMessage=""
                            errorMessage=""
                          />
                        )}
                      </div>
                    )}
                  </div>
                </aside>
              )}
              {!draft && <Feedback feedback={action.feedback} />}
            </div>
          ) : undefined
        }
      >
        <section aria-labelledby={titleId} className={tablePanelClass + " space-y-5"}>
          {offer.issued && offer.draft && (
            <div className="flex flex-wrap items-center gap-2">
              <button
                type="button"
                disabled={pending || !!draft}
                aria-pressed={reviewingDraft}
                className={reviewingDraft ? primaryClass : outlineButtonClass}
                onClick={() => setShowIssued(false)}
              >
                {l.draft}
              </button>
              <button
                type="button"
                disabled={pending || !!draft}
                aria-pressed={!reviewingDraft}
                className={reviewingDraft ? outlineButtonClass : primaryClass}
                onClick={() => setShowIssued(true)}
              >
                {l.issued}
              </button>
            </div>
          )}
          <div className="hidden print:block">
            <OfferAddresses sender={issued ?? sender} recipient={recipient} labels={l} />
          </div>
          <header>
            <h1
              id={titleId}
              aria-label={values.title || l.title}
              className="border-b border-border pb-2 text-xl font-semibold wrap-anywhere"
            >
              {field("title")}
            </h1>
            <dl className="grid grid-cols-[auto_1fr] gap-x-4 gap-y-1 border-b border-border py-3 text-sm">
              <dt>{l.date}</dt>
              <dd className="tabular-nums">{field("date")}</dd>
              <dt>{l.validUntil}</dt>
              <dd className="tabular-nums">{field("validUntil")}</dd>
            </dl>
          </header>
          {content.notes && (
            <section className="text-sm">
              <h2 className="font-semibold">{l.notes}</h2>
              <div className={!values.notes ? "text-muted-foreground" : undefined}>
                {field("notes")}
              </div>
            </section>
          )}
          <OfferLineTable
            labels={l}
            money={money}
            totals={totals}
            lineActions={canEdit}
            inlineEditing={canEdit}
            onAddLine={canEdit ? () => add(emptyLine(), true) : undefined}
            addLineDisabled={!editable || values.lines.length >= 200}
          >
            {values.lines.map((line, i) => (
              <tr
                className={cn(tableRowClass, "group/offer-line", order.rowClass(line.key))}
                key={line.key}
              >
                <OfferLinePosition
                  position={i + 1}
                  labels={l}
                  controls={canEdit ? order.controls(line.key, i) : undefined}
                />
                <td className={cn(tableCellClass, "wrap-anywhere")}>
                  {lineField(line, i, "description", l.description)}
                </td>
                <td className={cn(tableCellClass, "text-end tabular-nums")}>
                  <div className="flex flex-wrap items-center justify-end gap-x-1">
                    {lineField(line, i, "quantityMilli", l.quantity)}
                    {(canEdit || line.unit) &&
                      lineField(line, i, "unit", l.unit, line.unit || (canEdit ? "—" : ""))}
                  </div>
                </td>
                {(
                  [
                    [
                      "priceMinor",
                      l.price,
                      validAmounts[i] ? money(parsed[i].priceMinor) : line.priceMinor,
                    ],
                    ["discountBps", l.discount, line.discountBps && line.discountBps + "%"],
                    ["taxBps", l.tax, line.taxBps && line.taxBps + "%"],
                  ] as const
                ).map(([name, label, display]) => (
                  <td key={name} className={cn(tableCellClass, offerNumericColumnClass)}>
                    {lineField(line, i, name, label, display)}
                  </td>
                ))}
                <td className={cn(tableCellClass, offerNumericColumnClass)}>
                  {validAmounts[i] ? money(lineAmounts(parsed[i]).net) : "—"}
                </td>
                {canEdit && (
                  <td className={cn(tableActionCellClass, "py-0 print:hidden")}>
                    <IconTooltip label={l.remove}>
                      <button
                        type="button"
                        aria-label={l.remove}
                        className={cn(rowButtonClass, destructiveActionClass, rowControlClass)}
                        disabled={!editable}
                        onClick={() =>
                          updateLines((lines) => lines.filter((item) => item.key !== line.key))
                        }
                      >
                        <Trash2Icon aria-hidden="true" />
                      </button>
                    </IconTooltip>
                  </td>
                )}
              </tr>
            ))}
          </OfferLineTable>
          {canEdit && renderProductPicker && values.lines.length < 200 && (
            <details className="text-sm print:hidden">
              <summary className="w-fit cursor-pointer rounded-sm focus-visible:ring-2 focus-visible:ring-ring">
                {l.selectProduct}
              </summary>
              <fieldset disabled={!editable} className="mt-2">
                {renderProductPicker(add)}
              </fieldset>
            </details>
          )}
          {(values.terms || canEdit) && (
            <section className={cn("text-sm", !values.terms && "print:hidden")}>
              {values.terms && <h2 className="font-semibold">{l.terms}</h2>}
              <div>{field("terms")}</div>
            </section>
          )}
          {!content.notes && (canEdit || values.notes) && (
            <div className={cn("text-sm", !values.notes && "text-muted-foreground print:hidden")}>
              {field("notes")}
            </div>
          )}
          {draft && (
            <Feedback
              feedback={invalid ? { error: true, message: l.invalid } : saveAction.feedback}
            />
          )}
          {draft && (
            <div className="flex flex-wrap justify-end gap-2 print:hidden">
              <button
                type="button"
                className={outlineButtonClass}
                disabled={pending}
                onClick={() => {
                  setDraft(null);
                  setInvalid(false);
                }}
              >
                {l.cancel}
              </button>
              <button type="button" className={primaryClass} disabled={pending} onClick={save}>
                {l.save}
              </button>
            </div>
          )}
        </section>
      </ContentSidebarLayout>
      {deletion.dialog}
    </article>
  );
}

"use client";

import { CalendarDaysIcon, PencilIcon } from "lucide-react";
import { useCallback, useRef, useState, type KeyboardEvent } from "react";
import { flushSync } from "react-dom";

import { inputClass } from "@/components/plugins/customers/ui";
import { cn } from "@/components/utils/cn";

export function InlineOfferField({
  label,
  value,
  display = value,
  onChange,
  type = "text",
  maxLength,
  min,
  indicator = false,
  startEditing = false,
  contentEditable = false,
}: {
  label: string;
  value: string;
  display?: string;
  onChange?: (value: string) => void;
  type?: "text" | "date" | "decimal" | "textarea";
  maxLength?: number;
  min?: string;
  indicator?: boolean;
  startEditing?: boolean;
  contentEditable?: boolean;
}) {
  const [editing, setEditing] = useState(startEditing);
  const original = useRef(value);
  const trigger = useRef<HTMLButtonElement>(null);
  const input = useRef<HTMLInputElement | HTMLTextAreaElement | null>(null);
  const focus = useCallback((element: HTMLInputElement | HTMLTextAreaElement | null) => {
    input.current = element;
    element?.focus();
  }, []);

  const focusEditable = useCallback((element: HTMLDivElement | null) => {
    if (!element) return;
    // Let the browser own the text and caret for the duration of the edit.
    element.textContent = original.current;
    element.focus();
    element.ownerDocument.getSelection()?.collapse(element, element.childNodes.length);
  }, []);

  function onKeyDown(event: KeyboardEvent<HTMLElement>) {
    if (event.nativeEvent.isComposing) return;
    if (event.key !== "Escape" && (event.key !== "Enter" || type === "textarea")) return;
    event.preventDefault();
    flushSync(() => {
      if (event.key === "Escape") onChange?.(original.current);
      setEditing(false);
    });
    trigger.current?.focus();
  }

  function updateEditable(element: HTMLDivElement) {
    const text = element.innerText;
    const normalized = type === "textarea" ? text : text.replace(/[\r\n]/g, "");
    const next = maxLength !== undefined && normalized.length > maxLength ? value : normalized;
    if (next !== text) {
      element.textContent = next;
      element.ownerDocument.getSelection()?.collapse(element, element.childNodes.length);
    }
    onChange?.(next);
  }

  if (!onChange) return <span className="wrap-anywhere whitespace-pre-wrap">{display}</span>;
  const Icon = type === "date" ? CalendarDaysIcon : PencilIcon;
  if (editing && contentEditable) {
    return (
      <div
        ref={focusEditable}
        tabIndex={0}
        // oxlint-disable-next-line jsx-a11y/prefer-tag-over-role -- Name the contenteditable field as a textbox.
        role="textbox"
        aria-label={label}
        aria-multiline={type === "textarea" || undefined}
        contentEditable="plaintext-only"
        inputMode={type === "decimal" ? "decimal" : undefined}
        spellCheck={type === "decimal" ? false : undefined}
        className={cn(
          inputClass,
          "h-auto min-h-8 min-w-0 px-2 py-1 text-start wrap-anywhere whitespace-pre-wrap",
        )}
        onInput={(event) => {
          if (!(event.nativeEvent instanceof InputEvent && event.nativeEvent.isComposing)) {
            updateEditable(event.currentTarget);
          }
        }}
        onCompositionEnd={(event) => updateEditable(event.currentTarget)}
        onKeyDown={onKeyDown}
        onBlur={() => setEditing(false)}
      />
    );
  }
  if (editing) {
    const props = {
      ref: focus,
      value,
      "aria-label": label,
      maxLength,
      onKeyDown,
      onBlur: () => setEditing(false),
    };
    return type === "textarea" ? (
      <textarea
        {...props}
        rows={1}
        className={cn(inputClass, "field-sizing-content min-h-8 min-w-24 py-1")}
        onChange={(event) => onChange(event.target.value)}
      />
    ) : (
      <input
        {...props}
        type={type === "date" ? "date" : "text"}
        min={min}
        inputMode={type === "decimal" ? "decimal" : undefined}
        className={cn(inputClass, "h-8 px-2 text-inherit", type === "date" ? "w-auto" : "min-w-16")}
        onChange={(event) => onChange(event.target.value)}
      />
    );
  }

  return (
    <button
      ref={trigger}
      type="button"
      aria-label={display && display !== label ? label + ": " + display : label}
      className="group/field inline-flex max-w-full cursor-pointer items-center gap-2 rounded-sm text-start hover:bg-accent/50 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
      onClick={() => {
        original.current = value;
        if (type !== "date") {
          setEditing(true);
          return;
        }
        flushSync(() => setEditing(true));
        try {
          if (input.current instanceof HTMLInputElement) input.current.showPicker?.();
        } catch {
          // The focused date input still supports typing and its native picker.
        }
      }}
    >
      <span className="wrap-anywhere whitespace-pre-wrap">{display || label}</span>
      {indicator && (
        <Icon
          aria-hidden="true"
          className="size-4 shrink-0 group-hover/field:opacity-100 group-focus-visible/field:opacity-100 print:hidden [@media(hover:hover)]:opacity-0"
        />
      )}
    </button>
  );
}

"use client";

import { useRef, useState, type HTMLAttributes, type PointerEvent } from "react";

import type { OfferLine } from "@/components/plugins/offers/model";

export function editLine(line: OfferLine, digits: number, key: string) {
  return {
    key,
    description: line.description,
    unit: line.unit,
    quantityMilli: String(line.quantityMilli / 1000),
    priceMinor: (line.priceMinor / 10 ** digits).toFixed(digits),
    discountBps: String(line.discountBps / 100),
    taxBps: String(line.taxBps / 100),
  };
}
function scaled(value: string, digits: number) {
  if (!/^\d+(\.\d+)?$/.test(value)) return NaN;
  const [whole, frac = ""] = value.split(".");
  if (frac.length > digits) return NaN;
  return Number(whole + frac.padEnd(digits, "0"));
}
export function readLine(line: ReturnType<typeof editLine>, digits: number): OfferLine {
  return {
    description: line.description,
    unit: line.unit,
    quantityMilli: scaled(line.quantityMilli, 3),
    priceMinor: scaled(line.priceMinor, digits),
    discountBps: scaled(line.discountBps, 2),
    taxBps: scaled(line.taxBps, 2),
  };
}

export type OfferLineDraft = ReturnType<typeof editLine>;

export type OfferLineControls = {
  handle: HTMLAttributes<HTMLButtonElement>;
  moveUp: (() => void) | undefined;
  moveDown: (() => void) | undefined;
};

export function useOfferLineOrder(
  lines: OfferLineDraft[],
  update: (change: (lines: OfferLineDraft[]) => OfferLineDraft[]) => void,
  pending: boolean,
) {
  const drag = useRef<{ key: string; pointerId: number; startY: number } | null>(null);
  const [dropTarget, setDropTarget] = useState<{
    source: string;
    key: string;
    after: boolean;
  } | null>(null);
  function move(key: string, target: string, after: boolean) {
    update((current) => {
      const line = current.find((line) => line.key === key);
      if (!line || target === key) return current;
      const next = current.filter((line) => line.key !== key);
      const index = next.findIndex((line) => line.key === target);
      if (index < 0) return current;
      next.splice(index + Number(after), 0, line);
      return next;
    });
  }
  function cancelDrag() {
    drag.current = null;
    setDropTarget(null);
  }
  function getDropTarget(event: PointerEvent<HTMLButtonElement>) {
    const active = drag.current;
    if (
      pending ||
      !active ||
      active.pointerId !== event.pointerId ||
      Math.abs(event.clientY - active.startY) < 5
    )
      return null;
    const row = document
      .elementFromPoint(event.clientX, event.clientY)
      ?.closest<HTMLTableRowElement>("tr");
    if (!row || row.parentElement !== event.currentTarget.closest("tbody")) return null;
    const target = lines[row.sectionRowIndex];
    if (!target || target.key === active.key) return null;
    const { top, height } = row.getBoundingClientRect();
    return { source: active.key, key: target.key, after: event.clientY > top + height / 2 };
  }

  return {
    rowClass(key: string) {
      if (dropTarget?.source === key) return "opacity-50";
      if (dropTarget?.key !== key) return undefined;
      return dropTarget.after
        ? "[&>*]:shadow-[inset_0_-2px_0_var(--primary)]"
        : "[&>*]:shadow-[inset_0_2px_0_var(--primary)]";
    },
    controls(key: string, i: number): OfferLineControls {
      const previous = lines[i - 1];
      const next = lines[i + 1];
      const moveUp = !pending && previous ? () => move(key, previous.key, false) : undefined;
      const moveDown = !pending && next ? () => move(key, next.key, true) : undefined;
      const handle: OfferLineControls["handle"] = {
        onPointerDown: (event) => {
          if (event.button !== 0 || !event.isPrimary || pending) return;
          event.preventDefault();
          event.currentTarget.focus({ preventScroll: true });
          event.currentTarget.setPointerCapture(event.pointerId);
          drag.current = {
            key: key,
            pointerId: event.pointerId,
            startY: event.clientY,
          };
        },
        onPointerMove: (event) => {
          if (drag.current?.pointerId === event.pointerId) {
            const target = getDropTarget(event);
            if (target?.key !== dropTarget?.key || target?.after !== dropTarget?.after)
              setDropTarget(target);
          }
        },
        onPointerUp: (event) => {
          if (drag.current?.pointerId !== event.pointerId) return;
          const target = getDropTarget(event);
          cancelDrag();
          if (target) move(key, target.key, target.after);
        },
        onPointerCancel: cancelDrag,
        onLostPointerCapture: cancelDrag,
        onKeyDown: (event) => {
          if (event.key === "Escape" && drag.current) {
            const { pointerId } = drag.current;
            cancelDrag();
            if (event.currentTarget.hasPointerCapture(pointerId))
              event.currentTarget.releasePointerCapture(pointerId);
          }
          if (event.key !== "ArrowUp" && event.key !== "ArrowDown") return;
          event.preventDefault();
          if (event.key === "ArrowUp") moveUp?.();
          else moveDown?.();
        },
      };
      return { handle, moveUp, moveDown };
    },
  };
}

"use client";
import { PlusIcon, ArrowUpRightIcon } from "lucide-react";
import type { ComponentType } from "react";

import { IconTooltip } from "@/components/icon-tooltip";
import { Link, type LinkProps } from "@/components/link";
import { useLoadingActivity } from "@/components/loading-indicator";
import { NativeSelect } from "@/components/native-select";
import { StatusBadge } from "@/components/plugins/customers/ui";
import { offerLabels, type OfferLabels } from "@/components/plugins/offers/labels";
import {
  offerDefaultSort,
  offerSortFields,
  offerStatuses,
  formatOfferNumber,
  moneyFormatter,
  type OfferRow,
  type OfferStatus,
} from "@/components/plugins/offers/model";
import { TablePagination, type TablePaginationProps } from "@/components/table-pagination";
import { TableSearch } from "@/components/table-search";
import { TableSortHeader, useTableSort, type TableSortProps } from "@/components/table-sort";
import { primaryClass, iconButtonClass } from "@/components/utils/table-controls";
import {
  tableActionCellClass,
  tableActionHeaderClass,
  tableCellClass,
  tableClass,
  tablePanelClass,
  tableRowClass,
  tableHeaderClass,
} from "@/components/utils/table-styles";
export function OfferBadge({ status, labels }: { status: OfferStatus; labels: OfferLabels }) {
  const tones = {
    draft: "bg-muted text-muted-foreground",
    pending: "bg-status-pending text-status-pending-foreground",
    accepted: "bg-status-success text-status-success-foreground",
    declined: "bg-status-canceled text-status-canceled-foreground",
  };
  return (
    <StatusBadge
      value={status}
      options={offerStatuses.map((value) => ({ value, label: labels[value] }))}
      label={labels.status}
      className={tones[status]}
      successMessage=""
      errorMessage=""
    />
  );
}
export interface OffersListProps extends TableSortProps<(typeof offerSortFields)[number]> {
  rows: readonly OfferRow[];
  search: string;
  onSearchChange: (v: string) => void;
  status?: OfferStatus;
  onStatusChange: (v: OfferStatus | undefined) => void;
  customerId?: string;
  createHref?: string;
  getOfferHref: (id: string) => string;
  getCustomerHref: (id: string) => string;
  locale: string;
  pagination: TablePaginationProps;
  loading?: boolean;
  error?: string;
  labels?: Partial<OfferLabels>;
  linkComponent?: ComponentType<LinkProps>;
}
export function OffersList(props: OffersListProps) {
  const { rows, customerId, locale, linkComponent: A = Link } = props;
  const l = { ...offerLabels, ...props.labels };
  useLoadingActivity(!!props.loading);
  const headers = useTableSort(props, offerDefaultSort, undefined, {
    key: customerId ? "customer-offers" : "offers",
    fields: offerSortFields,
  });
  const columns = [
    "number",
    "title",
    ...(customerId ? [] : ["customer"]),
    "date",
    "validUntil",
    "status",
    "net",
    "gross",
    "emailStatus",
  ] as const;
  const visible = customerId ? rows.filter((r) => r.customerId === customerId) : rows;
  return (
    <section className={tablePanelClass}>
      <div className="mb-5 flex flex-wrap items-center justify-between gap-3">
        <h2 className="text-2xl font-semibold">{l.offers}</h2>
        <div className="flex flex-wrap items-center gap-2">
          <TableSearch value={props.search} onValueChange={props.onSearchChange} label={l.search} />
          <div>
            <NativeSelect
              className="h-10 rounded-lg border border-input bg-background px-2 text-sm"
              aria-label={l.status}
              value={props.status ?? ""}
              onChange={(e) =>
                props.onStatusChange(offerStatuses.find((s) => s === e.target.value))
              }
            >
              <option value="">{l.all}</option>
              {offerStatuses.map((s) => (
                <option key={s} value={s}>
                  {l[s]}
                </option>
              ))}
            </NativeSelect>
          </div>
          {props.createHref && (
            <A href={props.createHref} className={primaryClass}>
              <PlusIcon />
              {l.create}
            </A>
          )}
        </div>
      </div>
      <div className="overflow-x-auto">
        <table className={tableClass} aria-label={l.offers} aria-busy={!!props.loading}>
          <thead>
            <tr className={tableRowClass}>
              {columns.map((c) => {
                const field = offerSortFields.find((f) => f === c);
                return field ? (
                  <TableSortHeader
                    key={field}
                    {...headers}
                    field={field}
                    label={l[field]}
                    className={field === "net" || field === "gross" ? "text-right" : undefined}
                  />
                ) : (
                  <th key={c} scope="col" className={tableHeaderClass}>
                    {c === "customer" ? l.customer : l.emailStatus}
                  </th>
                );
              })}
              <th scope="col" className={tableActionHeaderClass}>
                {l.actions}
              </th>
            </tr>
          </thead>
          <tbody>
            {visible.map((r) => {
              const money = moneyFormatter(r.currency, locale).format;
              return (
                <tr key={r.id} className={tableRowClass}>
                  <td className={tableCellClass}>
                    <A className="font-medium underline" href={props.getOfferHref(r.id)}>
                      {formatOfferNumber(r.number)}
                    </A>
                  </td>
                  <th scope="row" className={tableCellClass + " text-left font-medium"}>
                    {r.title}
                  </th>
                  {!customerId && (
                    <td className={tableCellClass}>
                      <A href={props.getCustomerHref(r.customerId)} className="underline">
                        {r.customer}
                      </A>
                    </td>
                  )}
                  <td className={tableCellClass}>{r.date}</td>
                  <td className={tableCellClass}>{r.validUntil}</td>
                  <td className={tableCellClass}>
                    <OfferBadge status={r.status} labels={l} />
                  </td>
                  {[r.net, r.gross].map((v, i) => (
                    <td
                      key={i}
                      className={tableCellClass + " text-right whitespace-nowrap tabular-nums"}
                    >
                      {money(v)}
                    </td>
                  ))}
                  <td className={tableCellClass}>{r.sent ? l.sent : l.unsent}</td>
                  <td className={tableActionCellClass}>
                    <IconTooltip label={r.title}>
                      <A
                        aria-label={r.title}
                        className={iconButtonClass}
                        href={props.getOfferHref(r.id)}
                      >
                        <ArrowUpRightIcon />
                      </A>
                    </IconTooltip>
                  </td>
                </tr>
              );
            })}
            {(!visible.length || props.error) && (
              <tr>
                <td
                  colSpan={columns.length + 1}
                  className="p-6 text-center"
                  role={props.error ? "alert" : "status"}
                >
                  {props.error ?? (props.loading ? l.loading : l.empty)}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
      <TablePagination {...props.pagination} />
    </section>
  );
}
